#include <iostream>
#include <vector>
#include <array>
#include <cmath>
using namespace std;

constexpr int MOD = 1000000007;

long long mod_pow(long long base, long long exp) {
    long long result = 1;
    base %= MOD;
    while (exp > 0) {
        if (exp & 1) result = (result * base) % MOD;
        base = (base * base) % MOD;
        exp >>= 1;
    }
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    vector<vector<int>> prob(6, vector<int>(6));
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j) {
            int x;
            cin >> x;
            prob[i][j] = (int)((long long)x * mod_pow(100, MOD - 2) % MOD);
        }

    for (int i = n; i <= 5; ++i) prob[i][i] = 1;

    vector<int> combos;
    for (int mask = 0; mask < 64; ++mask)
        if (__builtin_popcount(mask) == 3)
            combos.push_back(mask);

    vector<long long> dp1(1 << 20, 0), dp2(1 << 20, 0);

    for (int mask = 0; mask < (1 << 18); ++mask) {
        array<array<bool, 6>, 6> grid{};
        long long prod = 1;
        int bit = 0;

        for (int r = 0; r < 6; ++r)
            for (int c = 0; c <= 2; ++c) {
                if (mask & (1 << bit)) {
                    grid[r][c] = true;
                    prod = (prod * prob[r][c]) % MOD;
                } else {
                    prod = (prod * ((1 - prob[r][c] + MOD) % MOD)) % MOD;
                }
                ++bit;
            }

        int comb_mask = 0;
        for (int idx = 0; idx < (int)combos.size(); ++idx) {
            int combo = combos[idx];
            int indices[3];
            int cnt = 0;
            for (int k = 0; k < 6; ++k)
                if (combo & (1 << k)) indices[cnt++] = k;

            if ((grid[indices[0]][0] && grid[indices[1]][1] && grid[indices[2]][2]) ||
                (grid[indices[0]][0] && grid[indices[2]][1] && grid[indices[1]][2]) ||
                (grid[indices[1]][0] && grid[indices[0]][1] && grid[indices[2]][2]) ||
                (grid[indices[1]][0] && grid[indices[2]][1] && grid[indices[0]][2]) ||
                (grid[indices[2]][0] && grid[indices[0]][1] && grid[indices[1]][2]) ||
                (grid[indices[2]][0] && grid[indices[1]][1] && grid[indices[0]][2]))
                comb_mask |= (1 << idx);
        }

        dp1[comb_mask] = (dp1[comb_mask] + prod) % MOD;
    }

    for (int mask = 0; mask < (1 << 18); ++mask) {
        array<array<bool, 6>, 6> grid{};
        long long prod = 1;
        int bit = 0;

        for (int r = 0; r < 6; ++r)
            for (int c = 3; c <= 5; ++c) {
                if (mask & (1 << bit)) {
                    grid[r][c] = true;
                    prod = (prod * prob[r][c]) % MOD;
                } else {
                    prod = (prod * ((1 - prob[r][c] + MOD) % MOD)) % MOD;
                }
                ++bit;
            }

        int comb_mask = 0;
        for (int idx = 0; idx < (int)combos.size(); ++idx) {
            int combo = combos[idx];
            int complement = combo ^ 63;
            int indices[3];
            int cnt = 0;
            for (int k = 0; k < 6; ++k)
                if (complement & (1 << k)) indices[cnt++] = k;

            if ((grid[indices[0]][3] && grid[indices[1]][4] && grid[indices[2]][5]) ||
                (grid[indices[0]][3] && grid[indices[2]][4] && grid[indices[1]][5]) ||
                (grid[indices[1]][3] && grid[indices[0]][4] && grid[indices[2]][5]) ||
                (grid[indices[1]][3] && grid[indices[2]][4] && grid[indices[0]][5]) ||
                (grid[indices[2]][3] && grid[indices[0]][4] && grid[indices[1]][5]) ||
                (grid[indices[2]][3] && grid[indices[1]][4] && grid[indices[0]][5]))
                comb_mask |= (1 << idx);
        }

        dp2[comb_mask] = (dp2[comb_mask] + prod) % MOD;
    }

    for (int bit = 0; bit < 20; ++bit)
        for (int mask = (1 << 20) - 1; mask >= 0; --mask)
            if (mask & (1 << bit))
                dp2[mask] = (dp2[mask] + dp2[mask ^ (1 << bit)]) % MOD;

    long long result = 0;
    for (int mask = 0; mask < (1 << 20); ++mask)
        result = (result + dp1[mask] * dp2[((1 << 20) - 1) ^ mask]) % MOD;

    cout << (1 - result + MOD) % MOD << '\n';
    return 0;
}
